package com.bank.largefile;

import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.logging.*;

public class LargeFileDemo {
    private static final Logger log = Logger.getLogger(LargeFileDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Path file = Files.createTempFile("transactions", ".csv");
        // Simulate a large file (write many lines). Each line: accountId,amount
        try (BufferedWriter w = Files.newBufferedWriter(file, StandardCharsets.UTF_8)) {
            for (int i = 0; i < 1_000_00; i++) {         // 100,000 lines for the demo
                w.write("SAV2001,100.00\n");
                w.write("CUR3001,250.00\n");
            }
        }

        var processor = new TransactionFileProcessor();

        BigDecimal viaReader = processor.totalForAccountViaReader(file, "SAV2001");
        log.info(() -> "BufferedReader total for SAV2001: Rs." + viaReader);

        BigDecimal viaStream = processor.totalForAccountViaStream(file, "SAV2001");
        log.info(() -> "Files.lines  total for SAV2001: Rs." + viaStream);

        // NOTE: we NEVER called Files.readAllLines — that would load the whole file.
        Files.deleteIfExists(file);
        log.info("Processed large file with BOUNDED memory (one line at a time)");
    }
}

// ─── Would be in service/TransactionFileProcessor.java ───
class TransactionFileProcessor {

    // Baseline: BufferedReader.readLine() — tiny, constant memory footprint.
    BigDecimal totalForAccountViaReader(Path file, String accountId) throws IOException {
        BigDecimal total = BigDecimal.ZERO;
        try (BufferedReader br = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
            String line;
            while ((line = br.readLine()) != null) {     // one line in memory at a time
                int comma = line.indexOf(',');
                if (comma > 0 && line.regionMatches(0, accountId, 0, comma)) {
                    total = total.add(new BigDecimal(line.substring(comma + 1)));
                }
            }
        }
        return total;
    }

    // Lazy stream: Files.lines() — MUST be closed (holds a file handle).
    BigDecimal totalForAccountViaStream(Path file, String accountId) throws IOException {
        try (var lines = Files.lines(file, StandardCharsets.UTF_8)) {   // try-with-resources!
            return lines
                    .filter(l -> l.startsWith(accountId + ","))
                    .map(l -> new BigDecimal(l.substring(l.indexOf(',') + 1)))
                    .reduce(BigDecimal.ZERO, BigDecimal::add);           // bounded result
        }
        // If we had done .collect(toList()) on the whole file, memory would blow up.
    }

    // For MAXIMUM speed on huge files (sketch): FileChannel + ByteBuffer.
    // You read raw bytes into a reusable buffer, decode with a CharsetDecoder,
    // split on '\n' yourself, and handle multi-byte chars crossing buffer edges.
    // Fastest but low-level and error-prone — use only when profiling demands it.
}
